window.NOTES={"version":55,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":39,"chapter":8,"section":"8.1","type":"填空","topic":"密码技术","title":"加密、解密、公钥与私钥","trigger":"真题从基本过程、非对称密钥分工、推导难度和效率考查密码技术。","conclusion":"加密用于保密，数字签名用于核验签署来源与数据完整性，摘要用于检测数据是否改变。三者目标不同；使用公钥前还必须确认它确实属于预期对象。","points":["对称加密由双方共享密钥，适合大量数据处理；非对称机制使用相关联的公钥与私钥，常用于身份认证、密钥建立或数字签名。","使用支持加密的公钥算法时，甲给乙发保密消息：甲用乙的公钥加密，乙用自己的私钥解密。要让谁读，就使用谁的加密公钥；私钥保密，公钥可公开但须确认归属。","甲要证明消息由自己签署：用甲的私钥生成签名，乙用甲的公钥验证。验证时同时需要收到的消息和签名；改动消息再配原签名，正常情况下验签失败。签名不是把“公钥加密”简单反过来用。","摘要通常不需要密钥，也没有对应的解密操作。收到消息后可重算摘要与可信原摘要比较；若攻击者能同时替换消息和摘要，二者一致仍不能证明消息来自谁。","数字签名可支持来源认证、完整性和不可否认性证据，但不自动隐藏内容，也不证明签署内容在现实世界中为真。","数字证书等机制可把身份与公钥建立可信绑定；若公钥本身被冒名替换，验签通过也不能据此确认预期身份。并非每种非对称算法都同时支持加密和签名。","非对称机制通常比对称加密慢，实际系统常用非对称机制建立或保护会话密钥，再用对称加密处理大量正文。","采用合适算法、安全参数并正确实现时，从公开密钥推导私钥在计算上应不可行；这不是数学上绝对不可能，也不保证薄弱参数或错误实现仍安全。","安全算法、参数与实现且私钥未泄露时，仅持公钥的接收方难以伪造签署者的有效签名。数字签名是按密码算法对消息生成的验证数据，不是手写签名照片；把照片加密传输也不等同于数字签名。"],"boundary":"验签成功表示签名与该消息、该公钥相匹配；是否可信还取决于公钥身份绑定和私钥管理。编码可逆不等于加密，普通摘要不等于签名。","id":"merged-15","sources":[{"year":2020,"q":39,"type":"填空"},{"year":2023,"q":29,"type":"多选"},{"year":2025,"q":43,"type":"填空"},{"year":2026,"q":44,"type":"填空"},{"year":2022,"q":50,"type":"填空"},{"year":2021,"q":30,"type":"多选","page":5}],"keys":["2020-39","2023-29","2025-43","2026-44","2022-50","2021-30"],"comparison":{"headers":["操作","使用什么","主要回答什么"],"rows":[["摘要","消息；通常无密钥","数据与已知摘要是否一致"],["对称加密 / 解密","双方共享的密钥","没有密钥者能否读取内容"],["公钥加密 / 私钥解密","接收者的公钥 / 私钥","让接收者恢复保密内容"],["私钥签名 / 公钥验签","签署者的私钥 / 公钥","签名是否匹配此消息与此公钥"],["证书验证","身份、公钥、签发者及信任关系","此公钥能否可信地关联到该身份"]]},"related":[{"id":"y2023q16","label":"HTTPS为HTTP通信增加加密与身份认证","reason":"HTTPS把传输加密与站点身份认证结合起来，是公钥可信绑定和会话保护的应用实例。"},{"id":"y2025q30","label":"生物识别、加密、入侵检测和数字签名都可保障安全","reason":"把加密、签名与身份识别、入侵检测并排比较，可按机密性、完整性和检测目标选择技术。"},{"id":"merged-17","label":"区块链结构、共识、可追溯性与信任边界","reason":"区块链同时使用哈希和签名，但难以篡改、验证签署者与隐藏内容仍是不同能力。"}],"pointGroups":[{"title":"加密方向、混合机制与计算条件","indices":[0,1,6,7]},{"title":"签名、摘要与身份可信的成立条件","indices":[2,3,4,5,8]}]},{"q":18,"target":null,"page":4,"chapter":8,"section":"8.1","topic":"钓鱼链接","title":"熟人转发和HTTPS都不能替你确认链接真实","conclusion":"打开消息中的链接前，应核对完整域名、来源和要求执行的动作；熟人账户也可能被盗用。","points":["仿冒站可借相似拼写、子域名和看似官方的路径混淆身份。","HTTPS保护连接传输，不保证网站运营者诚实，更不能证明消息本身真实。","涉及账号、支付和验证码时，主动从已知官方入口进入，并通过独立渠道核实。","不要在演示或陌生表单中输入真实账号密码、身份证号和验证码。"],"boundary":"“好友发来”“有锁标志”“页面长得像”都不足以建立信任；官方来源也要看准确地址与发布主体。","type":"单选","trigger":"围绕钓鱼链接的识别、应用与易错边界整理。","id":"y2021q18","sources":[{"year":2021,"q":18,"type":"单选"}],"keys":["2021-18"],"related":[{"id":"y2023q16","label":"HTTPS为HTTP通信增加加密与身份认证","reason":"理解HTTPS实际保护的传输与证书范围，才能解释为什么带锁图标的仿冒站仍需警惕。"},{"id":"y2026q14","label":"URL由协议、主机和资源路径等部分组成","reason":"拆出真正的主机部分，防止被路径中的机构名、相似拼写或子域名误导。"},{"id":"y2020q28","label":"病毒具有破坏性，安全仍需多层措施","reason":"链接和附件核实是多层防护的一环，还需配合更新、安全软件、独立备份和账户保护。"}]},{"q":39,"target":null,"chapter":8,"section":"8.1","topic":"网络结构与安全","title":"网络拓扑和分区会影响攻击扩散与可用性","conclusion":"安全不只取决于软件：连接路径、信任边界和单点故障也会改变风险。","points":["把所有设备放在同一可互访网段，可能扩大横向移动范围。","划分网络区域并按最小权限放行，有助于限制攻击传播，但不能保证绝对隔离。","关键链路和设备冗余可降低部分单点故障风险；仍需检测、切换机制和安全配置。"],"boundary":"拓扑结构既影响性能，也影响攻击路径和故障影响范围。","type":"判断","trigger":"从网络结构与安全的判断与应用整理。","id":"y2022q39","sources":[{"year":2022,"q":39,"type":"判断"}],"keys":["2022-39"],"related":[{"id":"merged-16","label":"防火墙与网络访问控制","reason":"网络分区只有配合明确的方向、地址和端口规则，才能把信任边界落实为访问控制。"},{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"关键链路或设备成为单点故障时主要影响可用性，可据此辨认拓扑设计的安全目标。"}]},{"q":39,"chapter":8,"section":"8.1","type":"判断","topic":"VPN","title":"VPN在公共网络上建立受保护的逻辑专用连接","trigger":"题目判断VPN是否能把公共网络上的连接作为内部网络的安全延伸。","conclusion":"VPN通过隧道、加密和认证等机制，在公共网络上建立受保护的逻辑连接，可用于远程接入或站点互联。","points":["远程接入VPN把授权终端接入组织网络。","站点到站点VPN连接两个或多个局域网。","安全性取决于协议、密钥、身份认证、终端状态和配置。"],"boundary":"VPN不会把公共互联网物理变成私有线路，也不会自动阻止终端中毒、钓鱼和越权访问。","id":"y2023q39","sources":[{"year":2023,"q":39,"type":"判断"}],"keys":["2023-39"],"related":[{"id":"merged-15","label":"加密、解密、公钥与私钥","reason":"VPN依赖加密与认证，应继续区分共享密钥、公私钥和身份绑定所解决的问题。"},{"id":"merged-16","label":"防火墙与网络访问控制","reason":"终端通过VPN接入后仍需受访问规则约束，受保护的连接不等于获得组织内全部资源权限。"}]},{"q":49,"chapter":8,"section":"8.1","type":"填空","topic":"拒绝服务攻击","title":"DoS/DDoS通过耗尽资源破坏可用性","trigger":"题目描述攻击者发送大量请求，使文件服务器无法向正常用户提供服务。","conclusion":"大量请求耗尽资源、使合法用户无法获得服务，属于拒绝服务攻击（DoS）；只有明确多个分布式攻击源时，才进一步判断为DDoS。","points":["攻击主要破坏信息系统的可用性。","流量清洗、限速、扩容、访问控制和异常检测可共同缓解。","IDS用于检测可疑活动，本身不是攻击类型。"],"boundary":"服务不可用也可能由故障或突发合法流量造成，需结合日志、流量来源和行为模式判断。","id":"y2024q49","sources":[{"year":2024,"q":49,"type":"填空"}],"keys":["2024-49"],"related":[{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"拒绝服务的直接后果是授权用户无法使用服务，因而主要破坏可用性。"},{"id":"merged-16","label":"防火墙与网络访问控制","reason":"访问控制可参与缓解攻击，但防火墙只控制经过检查路径的流量，不能单独保证服务一直可用。"}],"workedExamples":[{"year":2024,"q":49,"questionSummary":"大量连接请求让服务器无法正常提供服务，识别攻击类型。","reasoning":["题设的直接后果是合法用户无法得到服务，受损属性是可用性。","通过耗尽连接、带宽或处理资源造成拒绝服务，对应DoS。","只有题目进一步说明攻击流量来自多个分布式来源时，才有依据明确写DDoS；单凭大量请求不能推出分布式。"],"pitfall":"看见流量很多就直接判DDoS；或把不可用错当数据泄露。","transfer":"换一种资源耗尽情境仍先看受损属性：读不到是可用性，内容被改是完整性，秘密被读取是保密性。","sourceURL":"https://www.aipta.com/article/10360.html","sourceStatus":"公开转录题面已读，原卷扫描待核","historicalVersionNote":""}]},{"q":30,"chapter":8,"section":"8.1","type":"多选","topic":"安全技术","title":"生物识别、加密、入侵检测和数字签名都可保障安全","trigger":"题目要求选择用于保障信息安全的技术。","conclusion":"身份识别、机密性保护、攻击检测和完整性认证分别由不同安全技术承担，应形成纵深防御。","points":["人脸识别属于生物特征身份认证。","加密保护数据机密性。","入侵检测发现可疑行为，数字签名验证来源与完整性。"],"boundary":"单一技术不能覆盖所有安全目标；生物特征也需要模板保护和备用认证机制。","id":"y2025q30","sources":[{"year":2025,"q":30,"type":"多选"}],"keys":["2025-30"],"related":[{"id":"merged-15","label":"加密、解密、公钥与私钥","reason":"详细区分加密保护内容、签名验证来源与完整性、摘要检测变化，避免把所有密码技术都叫加密。"},{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"先明确机密性、完整性和可用性，再判断题目中的安全技术主要满足哪一个目标。"},{"id":"y2020q28","label":"病毒具有破坏性，安全仍需多层措施","reason":"多种安全技术须与补丁、备份、最小权限和用户判断配合，才能覆盖恶意软件带来的不同后果。"}]},{"q":16,"chapter":8,"section":"8.1","type":"单选","topic":"可用性","title":"过载与宕机会破坏信息系统可用性","trigger":"题目以系统过载或崩溃考查信息安全基本属性。","conclusion":"系统无法在需要时为授权用户提供服务，主要破坏可用性。","points":["机密性防止未授权泄露：成绩未被修改，但被无权查看的人读取，主要是机密性受损。","完整性防止未经授权的篡改或破坏：有人把成绩65改为95，即使系统仍可登录，完整性也已受损。","可用性要求授权用户在需要时能及时访问系统和信息：成绩数据仍在，但查询系统过载打不开，主要是可用性受损。"],"boundary":"一次事件可能同时影响多种属性，答题时应抓住题干直接后果。","id":"y2026q16","sources":[{"year":2026,"q":16,"type":"单选"}],"keys":["2026-16"],"related":[{"id":"y2024q49","label":"DoS/DDoS通过耗尽资源破坏可用性","reason":"DoS/DDoS是破坏可用性的具体方式，但普通故障和合法流量过载也可能造成同一后果。"},{"id":"y2022q39","label":"网络拓扑和分区会影响攻击扩散与可用性","reason":"网络冗余、检测和切换机制针对单点故障风险，可把可用性目标落实为连接与设备设计。"}],"pointGroups":null},{"q":28,"chapter":8,"section":"8.2","type":"多选","topic":"病毒与纵深防御","title":"病毒具有破坏性，安全仍需多层措施","trigger":"真题从病毒删除文件、降低效率，以及邮件、补丁、账户和杀毒软件的能力边界考查安全。","conclusion":"病毒造成数据损坏、资源耗尽或系统异常体现破坏性；防护必须由补丁、最小权限、安全软件、备份和用户判断共同组成。","points":["病毒还具有寄生性、传染性、潜伏性和触发性等常见特征。","安全软件可能漏报、误报或来不及识别新威胁。","离线或不可变备份能降低数据破坏和勒索软件损失。","病毒不仅可能感染可执行程序，也可能依附宏、启动区等；不能凭文件不是.exe就断言安全。","防护应落实到操作：可疑邮件链接和附件先独立核实；及时安装官方安全更新；使用安全软件、独立备份与长且唯一的密码，支持时启用多因素认证。"],"boundary":"破坏性不等于立即发作；任何单一产品也不能保证绝对安全。","id":"y2020q28","sources":[{"year":2020,"q":28,"type":"多选"},{"year":2023,"q":49,"type":"填空"},{"year":2024,"q":39,"type":"判断"},{"year":2022,"q":19,"type":"单选"}],"keys":["2020-28","2023-49","2024-39","2022-19"],"related":[{"id":"y2021q18","label":"熟人转发和HTTPS都不能替你确认链接真实","reason":"可疑消息的独立核实是具体防护步骤，熟人转发和HTTPS都不能取代对链接与动作的判断。"},{"id":"merged-16","label":"防火墙与网络访问控制","reason":"允许通过防火墙的连接仍可能携带恶意内容，网络访问控制与恶意软件防护必须配合。"},{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"扩展名参与类型识别却不保证内容安全，改名或隐藏后缀也不会把内部格式或恶意行为变掉。"}],"pointGroups":[{"title":"病毒特征与可能依附的载体","indices":[0,3]},{"title":"识别局限、备份与日常防护","indices":[1,2,4]}]},{"q":40,"chapter":8,"section":"8.3","type":"填空","topic":"防火墙","title":"防火墙与网络访问控制","trigger":"三道题从边界防护、内网保护和访问控制角度考查防火墙。","conclusion":"防火墙按规则控制经过它的网络流量。判断允许还是阻止，要把同一请求的方向、协议、地址和端口等条件一起代入规则，再考虑未匹配时的默认动作。","points":["规则可结合源地址、目标地址、协议、端口和流量方向；具备相应能力的防火墙还可检查连接状态或应用信息。","一条规则中设置的各项条件通常需要同时满足。例如允许管理网段访问 TCP 3389，不等于允许该网段访问全部端口，也不等于允许任意来源访问 3389。","未匹配明确规则的流量按默认动作处理。默认拒绝、只开放确有需要的流量，是常用的收紧策略；不能假定任何防火墙都天然采用相同默认值。","多条规则同时相关时，结果取决于产品的处理方式与优先级；教学模型可采用自上而下首条匹配，但应明确这是模型规则。","防火墙既可部署在网络边界，也可运行在单台主机上；它只能控制经过自身检查路径的流量，记录日志与阻止流量也是两个动作。","防火墙不是全面防毒工具，允许通过的连接仍可能携带恶意内容；它不能代替更新补丁、身份认证、恶意软件防护、备份和安全意识。"],"boundary":"下表假设目标是同一台服务器、规则只允许来自 10.20.0.0/16 的入站 TCP 3389，其余默认拒绝。不要仅凭“内网地址”或“端口已开放”就判定一次访问一定获准。","id":"merged-16","sources":[{"year":2020,"q":40,"type":"填空"},{"year":2025,"q":16,"type":"单选"},{"year":2026,"q":17,"type":"单选"},{"year":2022,"q":29,"type":"多选"},{"year":2021,"q":39,"type":"填空","page":6}],"keys":["2020-40","2025-16","2026-17","2022-29","2021-39"],"comparison":{"headers":["同一服务器收到的请求","是否满足允许规则","结果"],"rows":[["10.20.8.16 → TCP 3389（入站）","来源、协议、端口和方向均满足","允许"],["203.0.113.27 → TCP 3389（入站）","来源不在管理网段","默认拒绝"],["10.20.8.16 → TCP 80（入站）","端口不符","默认拒绝"],["10.20.8.16 → UDP 3389（入站）","协议不符","默认拒绝"]]},"related":[{"id":"y2022q39","label":"网络拓扑和分区会影响攻击扩散与可用性","reason":"网络分区划定信任边界，防火墙规则决定跨区流量如何放行，两者共同限制攻击传播范围。"},{"id":"y2021q15","label":"网卡连接本机与网络，路由器负责跨网转发","reason":"有网卡、默认网关和路由只说明接入及转发路径，请求是否获准还要代入访问规则。"},{"id":"y2020q28","label":"病毒具有破坏性，安全仍需多层措施","reason":"防火墙不能覆盖被允许连接中的全部恶意内容，也不能替代补丁、安全软件和备份。"}],"pointGroups":[{"title":"把同一请求的各项条件一起匹配","indices":[0,1]},{"title":"检查默认动作与规则优先级","indices":[2,3]},{"title":"检查部署路径与防护范围","indices":[4,5]}]},{"q":20,"chapter":8,"section":"8.5","type":"单选","topic":"信息伦理","title":"网络行为要尊重权限、署名与责任边界","trigger":"真题从未授权访问和改写他人成果考查信息伦理。","conclusion":"使用网络与信息资源应遵守访问权限、许可条款和法定使用限制，诚实标明来源并对传播后果负责；改写措辞也不能抹去他人贡献。","points":["访问权限决定能否读取、修改或传播数据。","引用应使来源和贡献边界可追溯。","传播前要核验事实、隐私、授权与潜在伤害。","账号、文件和数据的访问授权，与作品使用的著作权规则应分别判断。为介绍、评论作品或说明问题而适当引用已发表作品，符合著作权法第二十四条条件时可免许可；仍须指明作者及作品，不妨碍作品正常使用，不损害权利人的合法权益。署名并不等于可无限复制。"],"boundary":"“技术上能做到”不等于“有权做”；没有逐字复制也不自动排除抄袭。","id":"y2020q20","sources":[{"year":2020,"q":20,"type":"单选"},{"year":2024,"q":19,"type":"单选"}],"keys":["2020-20","2024-19"],"related":[{"id":"y2026q30","label":"使用AI生成内容要核验、披露并尊重权利","reason":"AI参与创作与传播时同样要核验内容、说明来源并判断披露义务，生成方式不会消除权利边界。"},{"id":"y2025q37","label":"全文检索既能检索题录也可能获取全文","reason":"数据库全文能否获取由收录与权限决定，取得文件之后的引用和传播仍需另外判断授权。"}]},{"q":30,"chapter":8,"section":"8.5","type":"多选","topic":"生成式人工智能规范","title":"使用AI生成内容要核验、披露并尊重权利","trigger":"题目要求判断使用生成式人工智能时哪些做法合规。","conclusion":"应核验事实、尊重著作权与隐私，并在公开传播或特定场景中按适用规则标识、说明AI生成合成属性。","points":["不能把AI输出当成天然真实或权威来源。","引用他人资料和用于学术、创作时应按规范披露来源与AI参与程度。","我国现行规则区分显式标识与隐式标识，并规定服务提供者、传播平台和用户的相应义务。"],"boundary":"不是所有私人使用都要求相同形式的标识；应结合是否传播、平台规则、内容类型和具体法律规范判断。","version":"按2025年9月1日起施行的《人工智能生成合成内容标识办法》校正","id":"y2026q30","sources":[{"year":2026,"q":30,"type":"多选"}],"keys":["2026-30"],"related":[{"id":"y2025q20","label":"生成式人工智能能辅助多种任务，但输出必须核验","reason":"生成式模型可能输出错误事实或伪造出处，这是人工核验和说明AI参与程度的直接原因。"},{"id":"y2020q20","label":"网络行为要尊重权限、署名与责任边界","reason":"将AI内容的披露要求与通常的访问权限、署名和传播责任结合，避免把标识当作全部授权。"},{"id":"y2024q17","label":"信息检索从需求分析到结果评价形成闭环","reason":"核验模型输出需要明确问题、查找合适资源并评价来源，不能只重复询问同一个生成结果。"}]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
window.NOTE_REFERENCES={"merged-15":[["NIST FIPS 186-5：Digital Signature Standard","https://csrc.nist.gov/pubs/fips/186-5/final"],["NIST：Public Key Certificate 术语","https://csrc.nist.gov/glossary/term/public_key_certificate"],["MDN：SubtleCrypto.sign","https://developer.mozilla.org/en-US/docs/Web/API/SubtleCrypto/sign"],["MDN：SubtleCrypto.encrypt","https://developer.mozilla.org/en-US/docs/Web/API/SubtleCrypto/encrypt"],["MDN：SubtleCrypto.digest","https://developer.mozilla.org/en-US/docs/Web/API/SubtleCrypto/digest"],["Microsoft：公钥与私钥","https://learn.microsoft.com/en-us/windows/win32/seccrypto/public-private-key-pairs"]],"y2026q16":[["NIST：机密性定义","https://csrc.nist.gov/glossary/term/confidentiality"],["NIST：完整性定义","https://csrc.nist.gov/glossary/term/integrity"],["NIST：可用性定义","https://csrc.nist.gov/glossary/term/availability"]],"merged-16":[["NIST SP 800-41 Rev.1：防火墙与策略指南","https://csrc.nist.gov/pubs/sp/800/41/r1/final"],["NIST SP 800-41 Rev.1 正文：规则、状态检查与默认拒绝","https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-41r1.pdf"]],"y2020q20":[["著作权法第二十四条：使用限制","https://www.ncac.gov.cn/xxfb/flfg/flfg_532/202103/t20210309_50530.html"]]};
window.NOTE_DEMOS={"y2023q39":{"kind":"sequence","title":"让校外电脑通过VPN进入校园内网","task":"完成认证、建隧道、访问内网资源和断开四个真实状态。","steps":[{"label":"连接VPN网关并认证","detail":"网关验证账户、证书或多因素凭据。"},{"label":"协商密钥并建立隧道","detail":"公网中的报文被封装和加密。"},{"label":"访问授权的内网资源","detail":"逻辑上像接入组织网络，但仍受访问控制。"},{"label":"断开VPN","detail":"隧道和临时路由撤销，公网本身没有变成私有线路。"}]},"y2024q49":{"kind":"explore","title":"守住一台遭遇洪泛的文件服务器","task":"点击流量与防护模块，区分攻击、检测和缓解。","initial":"正常请求100次/秒，异常流量突然升到20万次/秒。","actions":[{"label":"大量请求耗尽资源","stage":"DoS/DDoS","result":"主要破坏服务可用性。","tone":"bad"},{"label":"IDS发出异常告警","stage":"检测系统","result":"IDS是防护组件，不是攻击名称。","tone":"good"},{"label":"限速与流量清洗","stage":"缓解措施","result":"过滤异常来源并保护后端容量。","tone":"good"},{"label":"服务器离线就一定被攻击","stage":"证据不足","result":"故障和突发合法流量也会造成不可用。","tone":"warn"}]},"y2025q30":{"kind":"explore","title":"把安全措施放到正确防线","task":"点击技术，观察它主要保护身份、机密性、检测还是完整性。","initial":"一套系统需要多层安全措施。","actions":[{"label":"人脸识别","stage":"身份认证","result":"用生物特征核验主体。","tone":"good"},{"label":"加密","stage":"机密性保护","result":"未授权者难以理解密文。","tone":"good"},{"label":"入侵检测","stage":"监测与告警","result":"发现可疑流量或行为。","tone":"good"},{"label":"数字签名","stage":"来源与完整性验证","result":"验证签名者和内容是否被篡改。","tone":"good"}]},"y2026q16":{"kind":"explore","title":"安全三属性受到了什么伤害","task":"点击事件，观察主要破坏机密性、完整性还是可用性。","initial":"同一事件可能影响多项，但考试通常抓最直接后果。","actions":[{"label":"服务器过载无法访问","stage":"可用性受损","result":"授权用户在需要时无法获得服务。","tone":"good"},{"label":"成绩被陌生人读取","stage":"机密性受损","result":"信息被未授权主体获知。","tone":"good"},{"label":"成绩被偷偷改动","stage":"完整性受损","result":"数据被未授权篡改。","tone":"good"}]},"y2020q28":{"kind":"explore","title":"先看病毒怎样破坏，再搭多层防线","task":"点击攻击表现和防护措施，观察“特征”与“对策”的对应关系。","initial":"病毒可以潜伏后再触发，任何单一防护都不够。","actions":[{"label":"删除文件并拖慢系统","stage":"破坏性","result":"危害数据完整性和系统可用性。","tone":"bad"},{"label":"不打开陌生附件","stage":"减少入口","result":"先阻断常见钓鱼和恶意附件。","tone":"good"},{"label":"及时安装补丁","stage":"修复漏洞","result":"应从可信渠道更新。","tone":"good"},{"label":"最小权限＋多因素认证","stage":"限制后果","result":"降低账户被盗和恶意程序提权风险。","tone":"good"},{"label":"只安装杀毒软件","stage":"防线不完整","result":"仍需要备份、防火墙、补丁和谨慎操作。","tone":"bad"}]},"y2020q20":{"kind":"choose","title":"先问“有没有授权”","task":"点击网络行为，观察权限、目的和影响三个判断维度。","options":[{"label":"给自己的设备安装安全更新","result":"有权限且降低风险，属于正当防护。","tone":"good"},{"label":"未经同意查看同学账号","result":"没有授权，即使没有修改内容也不合规。","tone":"bad"},{"label":"为好玩让网站无法访问","result":"破坏服务可用性，目的不能使行为正当。","tone":"bad"},{"label":"批量发送垃圾信息","result":"消耗资源并干扰他人，不符合网络伦理。","tone":"bad"}]},"y2026q30":{"kind":"explore","title":"发布AI内容前过三道门","task":"点击检查项，形成公开传播前的操作顺序。","initial":"AI输出已经生成，但还不能直接发布。","actions":[{"label":"核验事实","stage":"与可靠来源交叉检查","result":"生成内容可能包含虚构或过时信息。","tone":"good"},{"label":"检查权利","stage":"确认隐私、著作权与授权边界","result":"能生成不代表有权传播。","tone":"good"},{"label":"按场景标识","stage":"说明AI生成合成属性","result":"公开传播时遵守现行标识规则和平台要求。","tone":"good"},{"label":"直接发布恶搞内容","stage":"可能误导并侵害他人","result":"娱乐目的不能免除真实性和权利责任。","tone":"bad"}]}};
window.NOTE_NAVIGATION={"merged-15":{"related":[{"id":"y2023q16","label":"HTTPS为HTTP通信增加加密与身份认证","reason":"HTTPS把传输加密与站点身份认证结合起来，是公钥可信绑定和会话保护的应用实例。","chapter":6},{"id":"y2025q30","label":"生物识别、加密、入侵检测和数字签名都可保障安全","reason":"把加密、签名与身份识别、入侵检测并排比较，可按机密性、完整性和检测目标选择技术。","chapter":8},{"id":"merged-17","label":"区块链结构、共识、可追溯性与信任边界","reason":"区块链同时使用哈希和签名，但难以篡改、验证签署者与隐藏内容仍是不同能力。","chapter":9}],"topics":[{"id":"cmp-security-goals","title":"安全：加密、摘要、签名、证书与防火墙"}]},"y2021q18":{"related":[{"id":"y2023q16","label":"HTTPS为HTTP通信增加加密与身份认证","reason":"理解HTTPS实际保护的传输与证书范围，才能解释为什么带锁图标的仿冒站仍需警惕。","chapter":6},{"id":"y2026q14","label":"URL由协议、主机和资源路径等部分组成","reason":"拆出真正的主机部分，防止被路径中的机构名、相似拼写或子域名误导。","chapter":6},{"id":"y2020q28","label":"病毒具有破坏性，安全仍需多层措施","reason":"链接和附件核实是多层防护的一环，还需配合更新、安全软件、独立备份和账户保护。","chapter":8}],"topics":[{"id":"cmp-security-goals","title":"安全：加密、摘要、签名、证书与防火墙"}]},"y2022q39":{"related":[{"id":"merged-16","label":"防火墙与网络访问控制","reason":"网络分区只有配合明确的方向、地址和端口规则，才能把信任边界落实为访问控制。","chapter":8},{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"关键链路或设备成为单点故障时主要影响可用性，可据此辨认拓扑设计的安全目标。","chapter":8}],"topics":[]},"y2023q39":{"related":[{"id":"merged-15","label":"加密、解密、公钥与私钥","reason":"VPN依赖加密与认证，应继续区分共享密钥、公私钥和身份绑定所解决的问题。","chapter":8},{"id":"merged-16","label":"防火墙与网络访问控制","reason":"终端通过VPN接入后仍需受访问规则约束，受保护的连接不等于获得组织内全部资源权限。","chapter":8}],"topics":[]},"y2024q49":{"related":[{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"拒绝服务的直接后果是授权用户无法使用服务，因而主要破坏可用性。","chapter":8},{"id":"merged-16","label":"防火墙与网络访问控制","reason":"访问控制可参与缓解攻击，但防火墙只控制经过检查路径的流量，不能单独保证服务一直可用。","chapter":8}],"topics":[]},"y2025q30":{"related":[{"id":"merged-15","label":"加密、解密、公钥与私钥","reason":"详细区分加密保护内容、签名验证来源与完整性、摘要检测变化，避免把所有密码技术都叫加密。","chapter":8},{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"先明确机密性、完整性和可用性，再判断题目中的安全技术主要满足哪一个目标。","chapter":8},{"id":"y2020q28","label":"病毒具有破坏性，安全仍需多层措施","reason":"多种安全技术须与补丁、备份、最小权限和用户判断配合，才能覆盖恶意软件带来的不同后果。","chapter":8}],"topics":[]},"y2026q16":{"related":[{"id":"y2024q49","label":"DoS/DDoS通过耗尽资源破坏可用性","reason":"DoS/DDoS是破坏可用性的具体方式，但普通故障和合法流量过载也可能造成同一后果。","chapter":8},{"id":"y2022q39","label":"网络拓扑和分区会影响攻击扩散与可用性","reason":"网络冗余、检测和切换机制针对单点故障风险，可把可用性目标落实为连接与设备设计。","chapter":8}],"topics":[]},"y2020q28":{"related":[{"id":"y2021q18","label":"熟人转发和HTTPS都不能替你确认链接真实","reason":"可疑消息的独立核实是具体防护步骤，熟人转发和HTTPS都不能取代对链接与动作的判断。","chapter":8},{"id":"merged-16","label":"防火墙与网络访问控制","reason":"允许通过防火墙的连接仍可能携带恶意内容，网络访问控制与恶意软件防护必须配合。","chapter":8},{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"扩展名参与类型识别却不保证内容安全，改名或隐藏后缀也不会把内部格式或恶意行为变掉。","chapter":2}],"topics":[]},"merged-16":{"related":[{"id":"y2022q39","label":"网络拓扑和分区会影响攻击扩散与可用性","reason":"网络分区划定信任边界，防火墙规则决定跨区流量如何放行，两者共同限制攻击传播范围。","chapter":8},{"id":"y2021q15","label":"网卡连接本机与网络，路由器负责跨网转发","reason":"有网卡、默认网关和路由只说明接入及转发路径，请求是否获准还要代入访问规则。","chapter":6},{"id":"y2020q28","label":"病毒具有破坏性，安全仍需多层措施","reason":"防火墙不能覆盖被允许连接中的全部恶意内容，也不能替代补丁、安全软件和备份。","chapter":8}],"topics":[{"id":"cmp-security-goals","title":"安全：加密、摘要、签名、证书与防火墙"}]},"y2020q20":{"related":[{"id":"y2026q30","label":"使用AI生成内容要核验、披露并尊重权利","reason":"AI参与创作与传播时同样要核验内容、说明来源并判断披露义务，生成方式不会消除权利边界。","chapter":8},{"id":"y2025q37","label":"全文检索既能检索题录也可能获取全文","reason":"数据库全文能否获取由收录与权限决定，取得文件之后的引用和传播仍需另外判断授权。","chapter":6}],"topics":[]},"y2026q30":{"related":[{"id":"y2025q20","label":"生成式人工智能能辅助多种任务，但输出必须核验","reason":"生成式模型可能输出错误事实或伪造出处，这是人工核验和说明AI参与程度的直接原因。","chapter":9},{"id":"y2020q20","label":"网络行为要尊重权限、署名与责任边界","reason":"将AI内容的披露要求与通常的访问权限、署名和传播责任结合，避免把标识当作全部授权。","chapter":8},{"id":"y2024q17","label":"信息检索从需求分析到结果评价形成闭环","reason":"核验模型输出需要明确问题、查找合适资源并评价来源，不能只重复询问同一个生成结果。","chapter":6}],"topics":[]}};
